mapper.select:
SELECT id, tenant_id, aggregate_id, topic, tag, payload, attempt_count, last_error,
       published_at, next_attempt_at, claimed_until, claim_token, dead_lettered_at, created_at
FROM workflow_outbox_events
WHERE aggregate_id = #{aggregateId}
  AND tag = #{tag}
ORDER BY created_at ASC

mapper.update:
UPDATE workflow_outbox_events
SET attempt_count = attempt_count + 1, last_error = #{error}, next_attempt_at = #{nextAttemptAt},
    claimed_until = NULL, claim_token = NULL
WHERE id = #{id} AND claim_token = #{claimToken}
  AND published_at IS NULL AND attempt_count + 1 < #{maxAttempts}

UPDATE workflow_outbox_events
SET attempt_count = attempt_count + 1, last_error = #{error}, dead_lettered_at = #{deadLetteredAt},
    next_attempt_at = NULL, claimed_until = NULL, claim_token = NULL
WHERE id = #{id} AND claim_token = #{claimToken}
  AND published_at IS NULL AND attempt_count + 1 >= #{maxAttempts}
